АдресAPI = ЭтотОбъект.Объект.АдресGitAPI;
Репозиторий = ЭтотОбъект.Объект.РепозиторийGit;
Ветка = ЭтотОбъект.Объект.ВеткаGit;
Токен = ЭтотОбъект.Объект.ТокенGit;
КаталогЗнаний = ЭтотОбъект.Объект.КаталогБазыЗнанийGit;

Результат = "";

ЧастиРепозитория = СтрРазделить(Репозиторий, "/");
Если ЧастиРепозитория.Количество() < 2 Тогда
	Результат = "Ошибка: РепозиторийGit должен быть в формате owner/repo";
	Возврат;
КонецЕсли;

Владелец = ЧастиРепозитория[0];
ИмяРепозитория = ЧастиРепозитория[1];

URL = АдресAPI + "/repos/" + Владелец + "/" + ИмяРепозитория + "/git/trees/" + Ветка + "?recursive=1";

Заголовки = Новый Соответствие;
Заголовки.Вставить("Authorization", "Bearer " + Токен);
Заголовки.Вставить("User-Agent", "1C-Enterprise");
Заголовки.Вставить("Accept", "application/vnd.github+json");

HTTPЗапрос = Новый HTTPЗапрос(URL, Заголовки);
HTTPСоединение = Новый HTTPСоединение(АдресAPI, , , , , 30);

Попытка
	HTTPОтвет = HTTPСоединение.Получить(HTTPЗапрос);
	ТелоОтвета = HTTPОтвет.ПолучитьТелоКакСтроку();

	Если HTTPОтвет.КодСостояния <> 200 Тогда
		Результат = "Ошибка HTTP: " + HTTPОтвет.КодСостояния + Символы.ПС + ТелоОтвета;
		Возврат;
	КонецЕсли;

	ЧтениеJSON = Новый ЧтениеJSON;
	ЧтениеJSON.УстановитьСтроку(ТелоОтвета);
	Данные = ПрочитатьJSON(ЧтениеJSON);
	ЧтениеJSON.Закрыть();

	Дерево = Данные.tree;
	КоличествоФайлов = 0;
	СписокФайлов = "";

	Для каждого Элемент Из Дерево Цикл
		Если Элемент.type = "blob" Тогда
			Если Не ЗначениеЗаполнено(КаталогЗнаний) Или СтрНачинаетсяС(Элемент.path, КаталогЗнаний) Тогда
				КоличествоФайлов = КоличествоФайлов + 1;
				СписокФайлов = СписокФайлов + Элемент.path + Символы.ПС;
			КонецЕсли;
		КонецЕсли;
	КонецЦикла;

	Результат = "Количество файлов в базе знаний: " + КоличествоФайлов + Символы.ПС + Символы.ПС + "Список файлов:" + Символы.ПС + СписокФайлов;

Исключение
	Результат = "Исключение: " + ОписаниеОшибки();
КонецПопытки;
